$fieldName=fn($key)=>$fieldPrefix===''?$key:$fieldPrefix.'['.$key.']';
?>
<section class="package-config" data-hosting-feature-fields><h3>Website-Module & PHP</h3><input type="hidden" name="<?= e($fieldName('website_features_present')) ?>" value="1">
<?php if($caps): ?><p class="small muted">PHP-Versionen von ISPConfig gelesen · Server <?= (int)$caps['server_id'] ?> · <?= e($caps['server_type']) ?> · <?= date('d.m.Y H:i',(int)$caps['checked_at']) ?>. <a class="text-link" href="/admin/module?kategorie=hosting">Serveroptionen aktualisieren</a></p><?php else: ?><div class="info-box"><?= e($capsError) ?> PHP-Versionen stehen nach erfolgreicher Verbindung zur Auswahl.</div><?php endif ?>
<div class="form-grid"><?php foreach(hosting_feature_flags() as $key=>$label): ?><label class="checkbox-field"><input type="checkbox" name="<?= e($fieldName($key)) ?>" value="1" <?= $f[$key]?'checked':'' ?>><span><?= e($label) ?></span></label><?php endforeach ?></div>
<div class="form-grid"><label class="field"><span>Auto-Subdomain</span><select name="<?= e($fieldName('auto_subdomain')) ?>"><?php foreach(['none'=>'Keine','www'=>'www.','*'=>'*.'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $f['auto_subdomain']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label>
<label class="field"><span>PHP-Betriebsart</span><select name="<?= e($fieldName('php_mode')) ?>" data-hosting-php-mode><?php foreach($caps['php_modes']??hosting_php_modes() as $value=>$label): ?><option value="<?= e($value) ?>" <?= $f['php_mode']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label>
<label class="field"><span>PHP-Version</span><select name="<?= e($fieldName('php_version')) ?>" data-hosting-php-version><option value="0">Systemstandard<?= !empty($caps['default_php_label'])?' · '.e($caps['default_php_label']):'' ?></option><?php foreach($caps['php_versions']??[] as $id=>$version): ?><option value="<?= (int)$id ?>" data-php-modes="<?= e(implode(',',$version['modes'])) ?>" <?= (int)$f['php_version']===(int)$id?'selected':'' ?>><?= e($version['label']) ?></option><?php endforeach ?></select><small>Zusätzliche Versionen sind für PHP-FPM und Fast-CGI verfügbar.</small></label></div>
<p class="small muted">Diese Grundausstattung gilt für das feste Paket. Weitere Optionen kannst du darunter als enthaltene oder im Konfigurator wählbare Module zuordnen. Let's Encrypt setzt SSL voraus.</p></section>
